import pathlib,base64,hashlib,json
root=pathlib.Path('/content/mathvisionkid_t4_budget_3h_20261023')
payload={'training/actual_coverage.py': '', 'final_evidence_archive_runtime.py': ''}
previous={'training/actual_coverage.py': None, 'final_evidence_archive_runtime.py': '5e0fd4af4b4f8931a58e45785ab0a8a9a4ce0ee580f0808dc1e9b1377f254a0c'}
proofs={}
for name,b64 in payload.items():
 p=root/name;raw=base64.b64decode(b64)
 if p.exists() and p.read_bytes()!=raw and hashlib.sha256(p.read_bytes()).hexdigest()!=previous[name]:raise ValueError('unexpectedpriorcodehash:'+name)
 p.write_bytes(raw);proofs[name]=hashlib.sha256(raw).hexdigest()
